WITH vehicle_channel_sales AS ( SELECT CASE WHEN hd.hd_vehicle_count = 0 THEN 'Zero Vehicles' WHEN hd.hd_vehicle_count = 1 THEN 'One Vehicle' WHEN hd.hd_vehicle_count = 2 THEN 'Two Vehicles' ELSE 'Three+ Vehicles' END AS vehicle_group, CASE WHEN p.p_channel_tv = 'Y' THEN 'TV' WHEN p.p_channel_email = 'Y' THEN 'Email' WHEN p.p_channel_radio = 'Y' THEN 'Radio' ELSE 'Other' END AS promo_channel, SUM(ws.ws_net_paid_inc_tax) AS net_paid_inc_tax, COUNT(*) AS sales_cnt FROM web_sales ws JOIN household_demographics hd ON ws.ws_ship_hdemo_sk = hd.hd_demo_sk JOIN promotion p ON ws.ws_promo_sk = p.p_promo_sk JOIN web_page wp ON ws.ws_web_page_sk = wp.wp_web_page_sk GROUP BY hd.hd_vehicle_count, p.p_channel_tv, p.p_channel_email, p.p_channel_radio ) SELECT vehicle_group, promo_channel, net_paid_inc_tax, sales_cnt, ROUND(100.0 * net_paid_inc_tax / SUM(net_paid_inc_tax) OVER (PARTITION BY vehicle_group), 2) AS pct_of_group FROM vehicle_channel_sales ORDER BY vehicle_group, pct_of_group DESC LIMIT 30
